61	@RequestMapping("/api")
62	public class OwnerRestControllerV1 implements OwnersApi {
63	
64	    /** Minimal syntactic check for an email address: a non-empty local part, a single
65	     *  '@', and a dotted domain, none containing whitespace or a second '@'. */
66	    private static final Pattern EMAIL_PATTERN =
