106	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
107	    @Override
108	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
109	        Owner owner = this.clinicService.findOwnerById(ownerId);
110	        if (owner == null) {
111	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
112	        }
113	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
114	    }
115	
116	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
117	    @Override
118	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
119	        HttpHeaders headers = new HttpHeaders();
120	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
121	        if (owner.getRegistrationDate() == null) {
122	            owner.setRegistrationDate(LocalDate.now());
123	        }
124	        String telephone = telephoneNormalizer.normalize(owner.getTelephone());
125	        if (telephone == null) {
126	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
127	        }
128	        owner.setTelephone(telephone);
129	        String email = owner.getEmail();
130	        if (email != null) {
131	            email = email.trim();
132	            if (!EMAIL_PATTERN.matcher(email).matches()) {
133	                return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
134	            }
135	            owner.setEmail(email.toLowerCase(Locale.ROOT));
136	        }
137	        boolean telephoneInUse = this.clinicService.findAllOwners().stream()
138	            .map(Owner::getTelephone)
139	            .filter(Objects::nonNull)
140	            .map(telephoneNormalizer::normalize)
141	            .anyMatch(telephone::equals);
142	        if (telephoneInUse) {
143	            return new ResponseEntity<>(HttpStatus.CONFLICT);
144	        }
145	        String lastNameKey = normalizeIdentity(owner.getLastName());
146	        String addressKey = normalizeIdentity(owner.getAddress());
147	        if (!Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
148	            boolean householdDuplicate = this.clinicService.findAllOwners().stream()
149	                .anyMatch(existing -> normalizeIdentity(existing.getLastName()).equals(lastNameKey)
150	                    && normalizeIdentity(existing.getAddress()).equals(addressKey));
151	            if (householdDuplicate) {
152	                return new ResponseEntity<>(HttpStatus.CONFLICT);
153	            }
154	        }
155	        owner.setHouseholdId(householdId(lastNameKey, addressKey));
156	        owner.setCustomerCode(nextCustomerCode(owner.getLastName()));
157	        this.clinicService.saveOwner(owner);
158	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
159	        headers.setLocation(UriComponentsBuilder.newInstance()
160	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
161	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
162	    }
