164	    /**
165	     * Normalize a value for household-identity comparison: null becomes an empty
166	     * string, surrounding whitespace is trimmed, internal whitespace runs collapse
167	     * to a single space, and the result is lower-cased.
168	     */
169	    private static String normalizeIdentity(String value) {
170	        if (value == null) {
171	            return "";
172	        }
173	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
174	    }
175	
176	    /**
177	     * Build the stable, shared household identifier for an owner, formatted
178	     * {@code 'HH-<HEX12>'} where HEX12 is the first twelve upper-case hex characters
179	     * of the SHA-256 digest of the normalized lastName and address joined by '|'.
180	     * Owners in the same household (same normalized lastName and address) therefore
181	     * derive an identical householdId.
182	     */
183	    private static String householdId(String lastNameKey, String addressKey) {
184	        String source = lastNameKey + "|" + addressKey;
185	        try {
186	            byte[] digest = MessageDigest.getInstance("SHA-256")
187	                .digest(source.getBytes(StandardCharsets.UTF_8));
188	            StringBuilder sb = new StringBuilder(digest.length * 2);
189	            for (byte b : digest) {
190	                sb.append(String.format("%02x", b));
191	            }
192	            return "HH-" + sb.substring(0, 12).toUpperCase(Locale.ROOT);
193	        }
194	        catch (NoSuchAlgorithmException e) {
195	            throw new IllegalStateException("SHA-256 not available", e);
196	        }
197	    }
198	
199	    /**
200	     * Build the customer code assigned on create, formatted {@code '<LAST3>-<NNNN>'}:
201	     * LAST3 is the upper-cased first three letters of {@code lastName} and NNNN is a
202	     * global 4-digit zero-padded sequence equal to one more than the current number of
203	     * owners (e.g. 'SMI-0007').
204	     */
205	    private String nextCustomerCode(String lastName) {
206	        String last3 = lastName.substring(0, Math.min(3, lastName.length())).toUpperCase(Locale.ROOT);
207	        int sequence = this.clinicService.findAllOwners().size() + 1;
208	        return String.format("%s-%04d", last3, sequence);
209	    }
